parameters.jsCode:
const rawInput = $input.first().json;
const update = rawInput.body || rawInput;

if (!update || !update.callback_query) {
  return [];
}

// 1. Kiem tra webhook secret token (neu co cau hinh)
const webhookSecret = $env.TELEGRAM_WEBHOOK_SECRET;
const headers = rawInput.headers || {};
const incomingSecret = headers['x-telegram-bot-api-secret-token'];
if (webhookSecret && incomingSecret !== webhookSecret) {
  return [];
}

// 2. Kiem tra hop le chat_id (neu co cau hinh)
const authorizedChatId = $env.TELEGRAM_CHAT_ID;
const messageChatId = update.callback_query.message?.chat?.id;
if (authorizedChatId && String(messageChatId) !== String(authorizedChatId)) {
  return [];
}

// 3. Kiem tra user_id allowlist (neu co cau hinh)
const authorizedUserIds = $env.TELEGRAM_AUTHORIZED_USER_IDS;
const fromId = update.callback_query.from?.id;
if (authorizedUserIds && fromId) {
  const allowed = authorizedUserIds.split(',').map(s => s.trim());
  if (!allowed.includes(String(fromId))) {
    return [];
  }
}

// 4. Parse callback data va revision
const data = update.callback_query.data || "";
const [action, request_id, revisionStr] = data.split("|");

// Chi chap nhan action approve hoac revise hop le
if (action !== "approve" && action !== "revise") {
  return [];
}

const revision = revisionStr ? parseInt(revisionStr, 10) : 1;
const status = action === "approve" ? "APPROVED" : "NEEDS_REVISION";
const note = action === "approve" 
  ? `Approved via Telegram (r${revision})` 
  : `Needs revision via Telegram (r${revision})`;

const reviewer = update.callback_query.from.first_name || update.callback_query.from.username || "Unknown";

return [{
  json: {
    request_id: request_id,
    revision: revision,
    status: status,
    reviewed_by: reviewer,
    note: note,
    callback_query_id: update.callback_query.id,
    chat_id: messageChatId,
    message_id: update.callback_query.message?.message_id
  }
}];

